#!/usr/bin/env bash
#
# Package a tetra3rs pattern database as cedar-tetra3rs-db (Architecture: all).
#
#   build-tetra3rs-db-deb.sh --db <tetra3rs_db.bin> --version <version> --out <dir>
#                            [--description-note <text>]
#
# Installs /usr/share/cedar-tetra3rs-db/tetra3rs_db.bin, the path
# cedar-server-tetra3rs's systemd drop-in passes as CEDAR_TETRA3RS_DATABASE.
#
# The database is generated by make-tetra3rs-db. It is serialized with postcard
# and explicit little-endian fields, so it is the same on every architecture;
# hence "all". Its format follows the tetra3rs crate version, which is why the
# package version starts with it and cedar-server-tetra3rs depends on a
# matching major.minor range.

set -euo pipefail

here=$(cd "$(dirname "$0")" && pwd)
db="" version="" out="" note=""
package=cedar-tetra3rs-db

while [ $# -gt 0 ]; do
    case "$1" in
        --db)               db=$2; shift 2 ;;
        --version)          version=$2; shift 2 ;;
        --out)              out=$2; shift 2 ;;
        --description-note) note=$2; shift 2 ;;
        *) echo "unknown argument: $1" >&2; exit 2 ;;
    esac
done
[ -n "$db" ] && [ -n "$version" ] && [ -n "$out" ] || {
    echo "usage: $0 --db <file> --version <version> --out <dir>" >&2
    exit 2
}
[ -s "$db" ] || { echo "missing or empty database: $db" >&2; exit 1; }

owner=${GITHUB_REPOSITORY_OWNER:-cedar}
maintainer=${DEB_MAINTAINER:-"$owner <$owner@users.noreply.github.com>"}

work=$(mktemp --directory)
trap 'rm -rf "$work"' EXIT
stage="$work/stage"

install -D --mode=0644 "$db" "$stage/usr/share/$package/tetra3rs_db.bin"
install -D --mode=0644 "$here/tetra3rs-db.copyright" \
    "$stage/usr/share/doc/$package/copyright"

installed_size=$(du --summarize --block-size=1K "$stage" | cut --fields=1)
mkdir --parents "$stage/DEBIAN"
{
    echo "Package: $package"
    echo "Version: $version"
    echo "Architecture: all"
    echo "Maintainer: $maintainer"
    echo "Installed-Size: $installed_size"
    echo "Section: science"
    echo "Priority: optional"
    echo "Homepage: https://github.com/ssmichael1/tetra3rs"
    echo "Description: Star pattern database for Cedar's tetra3rs plate solver"
    echo " The pattern database cedar-server-tetra3rs loads at startup, generated"
    echo " by make-tetra3rs-db from the merged Gaia DR3 + Hipparcos-2 catalog that"
    echo " tetra3rs publishes. Installed as"
    echo " /usr/share/$package/tetra3rs_db.bin."
    if [ -n "$note" ]; then
        echo " ."
        echo " $note"
    fi
} > "$stage/DEBIAN/control"

mkdir --parents "$out"
deb="$out/${package}_${version}_all.deb"
dpkg-deb --root-owner-group -Zxz --build "$stage" "$deb" >/dev/null

echo "built $deb"
dpkg-deb --info "$deb"
dpkg-deb --contents "$deb"
